package br.com.onda;
import android.content.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class SearchIndexTest {
 @Test public void storedNotesCollectionsAndPointsAreSearchable(){Context c=getInstrumentation().getTargetContext();SharedPreferences p=c.getSharedPreferences("media_shelf",0);String old=p.getString("data",null);try{p.edit().putString("data","{\"v\":1}").commit();assertTrue(ShelfStore.edit(c,s->{MediaShelf.Item i=s.touch("pdf","content://search-test/guide","Guia de astronomia",2,10,12345);MediaShelf.Collection group=s.create("Astronomia");return s.add(group.id,i.id)&&s.note(i.id,"",1,"Nebulosa de Órion")&&s.note(i.id,"",4,"Observação noturna");}));java.util.List<UnifiedSearch.Entry> index=SearchIndex.load(c).entries;java.util.List<UnifiedSearch.Entry> notes=UnifiedSearch.find(index,"nebulosa orion",5);assertEquals(1,notes.size());assertEquals(1,notes.get(0).position);assertEquals("pdf",notes.get(0).targetType);assertEquals(1,UnifiedSearch.find(index,"observacao noturna",5).size());assertEquals(1,UnifiedSearch.find(index,"astronomia",4).size());assertEquals(2,UnifiedSearch.find(index,"guia astronomia",3).get(0).position);}finally{SharedPreferences.Editor e=p.edit();if(old==null)e.remove("data");else e.putString("data",old);e.commit();}}
 @Test public void customVoicePhraseKeepsPriority(){Context c=getInstrumentation().getTargetContext();SharedPreferences p=c.getSharedPreferences("voice_phrases",0);String old=p.getString("entries",null);try{VoicePhraseBook book=new VoicePhraseBook("[]");assertNotNull(WorkspaceVoice.parse("abra minha coleção estudo"));VoiceCommand command=VoiceCommand.parse("toque as favoritas");assertNotNull(book.put(null,"abra minha coleção estudo",command.action,command.query,command.minutes));assertTrue(VoicePhrases.save(c,book));assertNotNull(VoicePhrases.read(c).find("abra minha coleção estudo"));}finally{SharedPreferences.Editor e=p.edit();if(old==null)e.remove("entries");else e.putString("entries",old);e.commit();}}
}
